// Generic scene primitives: coordinates, groups, signal mappings and selection rules.
// No environment-specific components or executable expressions are stored here.
export const SIGNALS={
 'hand.angle':{label:'Hand rotation',min:-60,max:60,unit:'degrees'},
 'hand.x':{label:'Hand horizontal position',min:0,max:1,unit:'0–1'},
 'hand.y':{label:'Hand vertical position',min:0,max:1,unit:'0–1'},
 'hand.fingers':{label:'One-hand finger count',min:0,max:5,unit:'fingers'},
 'hands.row':{label:'Left-side finger count',min:0,max:5,unit:'fingers'},
 'hands.column':{label:'Right-side finger count',min:0,max:5,unit:'fingers'},
 'hands.index':{label:'Two-hand index (row × 6 + column)',min:0,max:35,unit:'0–35'}
};
export const PROPERTIES={rotation:'Group rotation',x:'Group horizontal offset',y:'Group vertical offset',scale:'Group size',cursorX:'Pointer horizontal position',cursorY:'Pointer vertical position',index:'Highlighted choice index'};
export const SELECTORS={pointer:'Click or tap a choice',target:'Choice nearest a fixed target',cursor:'Choice under a moving pointer',index:'Choice at the mapped index',scan:'Next / Select scanning',trace:'Trace the choices in order',swipe:'Recognize a word path'};
export const newGroup=()=>({id:crypto.randomUUID(),name:'Group',parent:'',pivotX:.5,pivotY:.5,x:0,y:0,rotation:0,scale:1});
export function newScene(){return {groups:[{...newGroup(),name:'Choices'}],bindings:[],selection:{mode:'pointer',x:.5,y:.12,radius:.1},gate:{enabled:false,signal:'hand.fingers',min:1,max:5}};}
export function newBinding(group){return {id:crypto.randomUUID(),signal:'hand.x',target:'x',group,inputMin:0,inputMax:1,outputMin:-.3,outputMax:.3,clamp:true};}
export function mapSignal(value,b){if(!Number.isFinite(value)||b.inputMin===b.inputMax)return null;let t=(value-b.inputMin)/(b.inputMax-b.inputMin);if(b.clamp)t=Math.max(0,Math.min(1,t));return b.outputMin+t*(b.outputMax-b.outputMin);}
export function groupChain(scene,id){const chain=[],seen=new Set();while(id){if(seen.has(id))throw new Error('Groups cannot contain a cycle.');seen.add(id);const group=scene.groups.find(g=>g.id===id);if(!group)throw new Error('A choice refers to a missing group.');chain.push(group);id=group.parent;}return chain;}
export function transformPoint(point,groups,inverse=false){let {x,y}=point;for(const g of inverse?groups.slice().reverse():groups){const a=g.rotation*Math.PI/180,c=Math.cos(a),s=Math.sin(a);if(inverse){const dx=x-g.x-g.pivotX,dy=y-g.y-g.pivotY;x=g.pivotX+(dx*c+dy*s)/g.scale;y=g.pivotY+(-dx*s+dy*c)/g.scale;}else{const dx=(x-g.pivotX)*g.scale,dy=(y-g.pivotY)*g.scale;x=g.pivotX+dx*c-dy*s+g.x;y=g.pivotY+dx*s+dy*c+g.y;}}return {x,y};}
export function resolveScene(block,signals={}){
 const scene=structuredClone(block.scene),cursor={x:.5,y:.5};let index=null,ready=true;
 for(const binding of scene.bindings){const value=mapSignal(signals[binding.signal],binding);if(value===null){ready=false;continue;}if(binding.target==='cursorX')cursor.x=value;else if(binding.target==='cursorY')cursor.y=value;else if(binding.target==='index')index=Math.round(value);else{const g=scene.groups.find(g=>g.id===binding.group);if(g)g[binding.target]=binding.target==='scale'?Math.max(.1,Math.min(4,value)):value;}}
 const mappingReady=ready;if(scene.gate.enabled){const v=signals[scene.gate.signal];if(!Number.isFinite(v)||v<scene.gate.min||v>scene.gate.max)ready=false;}
 const positions=block.items.map((item,i)=>{const chain=groupChain(scene,item.group),p=transformPoint(item,chain),scale=chain.reduce((n,g)=>n*g.scale,1);return {item,i,...p,w:(item.w||.12)*scale,h:(item.h||.1)*scale};});
 return {positions,cursor,index,ready,mappingReady,scene};
}
export function sceneTarget(resolved){const {scene,positions,cursor}=resolved;if(!resolved.ready)return null;const mode=scene.selection.mode;if(mode==='index')return positions[resolved.index]?.item.kind==='label'?null:positions[resolved.index]?.i??null;if(!['cursor','target'].includes(mode))return null;const point=mode==='cursor'?cursor:scene.selection;
 const visible=positions.filter(p=>p.item.kind!=='label'&&p.x>=0&&p.x<=1&&p.y>=0&&p.y<=1);if(mode==='cursor'){const hits=visible.filter(p=>Math.abs(point.x-p.x)<=p.w/2&&Math.abs(point.y-p.y)<=p.h/2);return hits.length===1?hits[0].i:null;}
 const ranked=visible.map(p=>({...p,d:Math.hypot(point.x-p.x,point.y-p.y)})).filter(p=>p.d<=scene.selection.radius).sort((a,b)=>a.d-b.d);if(!ranked.length||ranked[1]&&ranked[1].d-ranked[0].d<.012)return null;return ranked[0].i;
}
export function arrangeItems(block,ids,pattern,options={}){const items=block.items.filter(i=>ids.includes(i.id)),n=items.length;if(!n)return;const group=block.scene.groups.find(g=>g.id===items[0].group),cx=group?.pivotX??.5,cy=group?.pivotY??.5,r=options.radius??.36,columns=options.columns??Math.ceil(Math.sqrt(n));items.forEach((item,i)=>{if(pattern==='circle'){const a=(options.startAngle??-90)*Math.PI/180+i*2*Math.PI/n;item.x=cx+Math.cos(a)*r;item.y=cy+Math.sin(a)*r;item.w=item.h=Math.max(.035,Math.min(.12,2*r*2.8/n));}else if(pattern==='row'){item.x=.1+.8*(i+.5)/n;item.y=cy;item.w=Math.min(.14,.75/n);item.h=.12;}else if(pattern==='column'){item.x=cx;item.y=.1+.8*(i+.5)/n;item.w=.16;item.h=Math.min(.12,.75/n);}else{const rows=Math.ceil(n/columns);item.x=.1+.8*(i%columns+.5)/columns;item.y=.1+.8*(Math.floor(i/columns)+.5)/rows;item.w=Math.min(.16,.72/columns);item.h=Math.min(.14,.72/rows);}});}
export function validateScene(raw,items,unique){
 const fail=m=>{throw new Error(m);},num=(v,min,max)=>Number.isFinite(v)&&v>=min&&v<=max?v:fail('Invalid canvas value.'),text=(v,max)=>typeof v==='string'&&v.length<=max?v:fail('Invalid canvas text.'),one=(v,values)=>values.includes(v)?v:fail('Invalid canvas option.');
 if(!raw||!Array.isArray(raw.groups)||!raw.groups.length||raw.groups.length>16)fail('Use 1–16 groups per canvas.');if(!Array.isArray(raw.bindings)||raw.bindings.length>24)fail('Use up to 24 signal mappings per canvas.');
 const groups=raw.groups.map(g=>({id:unique(g.id),name:text(g.name,80),parent:text(g.parent,80),pivotX:num(g.pivotX,0,1),pivotY:num(g.pivotY,0,1),x:num(g.x,-2,2),y:num(g.y,-2,2),rotation:num(g.rotation,-720,720),scale:num(g.scale,.1,4)}));
 const bindings=raw.bindings.map(b=>({id:unique(b.id),signal:one(b.signal,Object.keys(SIGNALS)),target:one(b.target,Object.keys(PROPERTIES)),group:text(b.group,80),inputMin:num(b.inputMin,-1000,1000),inputMax:num(b.inputMax,-1000,1000),outputMin:num(b.outputMin,-1000,1000),outputMax:num(b.outputMax,-1000,1000),clamp:typeof b.clamp==='boolean'?b.clamp:fail('Invalid mapping limit.')}));
 const s=raw.selection,g=raw.gate;if(!s||!g)fail('Choose canvas selection rules.');const scene={groups,bindings,selection:{mode:one(s.mode,Object.keys(SELECTORS)),x:num(s.x,0,1),y:num(s.y,0,1),radius:num(s.radius,.02,.5)},gate:{enabled:typeof g.enabled==='boolean'?g.enabled:fail('Invalid condition toggle.'),signal:one(g.signal,Object.keys(SIGNALS)),min:num(g.min,-1000,1000),max:num(g.max,-1000,1000)}};
 for(const g of groups)groupChain(scene,g.id);for(const item of items)groupChain(scene,item.group);const targets=new Set();for(const b of bindings){if(b.inputMin===b.inputMax)fail('A mapping needs two different input values.');if(['rotation','x','y','scale'].includes(b.target)&&!groups.some(g=>g.id===b.group))fail('A mapping refers to a missing group.');const key=['rotation','x','y','scale'].includes(b.target)?b.group+':'+b.target:b.target;if(targets.has(key))fail('Map each property once. Combine different properties instead.');targets.add(key);}
 return scene;
}
export function sceneIssues(block){const s=block.scene,issues=[];if(s.selection.mode==='target'&&!s.gate.enabled&&!s.bindings.some(b=>['rotation','x','y','scale'].includes(b.target)))issues.push('Connect a hand signal to a group property, so choices can move toward the fixed target.');if(s.selection.mode==='cursor'&&!s.bindings.some(b=>['cursorX','cursorY'].includes(b.target)))issues.push('Connect a hand signal to the pointer position.');if(s.selection.mode==='index'&&!s.bindings.some(b=>b.target==='index'))issues.push('Connect a signal to the highlighted choice index.');if(['trace','swipe'].includes(s.selection.mode)&&s.bindings.length)issues.push('Keep choice positions fixed while recognizing a path; remove motion mappings or choose a selection rule.');return issues;}
export function syncSceneInput(block){const mode=block.scene.selection.mode;block.input.behavior=mode==='trace'?'trace':mode==='swipe'?'swipe':'select';block.input.source=mode==='scan'?'scan':['trace','swipe'].includes(mode)?'pen':mode==='pointer'&&!block.scene.bindings.length?'pointer':'scene';block.input.model=mode==='scan'?'personal':mode==='swipe'?'words':mode==='trace'?'none':block.input.source==='scene'?'hands':'none';block.input.scanStyle='linear';}
